function grid$hrdmnv(f){
  this.constructor(f);
}
grid$hrdmnv.prototype = new DirEvent();
grid$hrdmnv.prototype.afterInit = function(){
  var p = this._dir;

  if(!p.options._isReload){
    p.options._isReload = true;

    refreshSizeGridDir();
    $(window).resize(function() {
      console.log(8888);
      refreshSizeGridDir();
    });

    $('<div class="left-panel-tree" id="tree_left"><div id="tree_dept" class="tree-top"></div><div id="tree_info" class="tree-bottom"></div></div>').insertBefore("#content");
    p.request('ViewTreeDept', 'GetTable', null, loadTreeDept);
    p.request('ViewTreeInfo', 'GetTable', null, loadTreeInfo);
    //test
    var sBottomResize = '<div class="bottom-resize" id="bar_resize_grid"></div>'
    var ss = sBottomResize + document.getElementById("DIR_hrdmnv2_Grid").outerHTML;
    $(ss).insertAfter("#DIR_hrdmnv2_Grid");

    //--resize
  /*  var oG1Resize, oG2Resize, iStartY, iG1Height, isResize = false;
    var _funMoveResize = function (e) {
        if (isResize) {
            var h1 = iG1Height, h2 = iG2Height;
            h1 -= (iStartY - e.pageY);
            h2 += (iStartY - e.pageY);

            if (!(h1 <= 100 || h2 <= 100)){
                $(oG1Resize).height(h1);
                $(oG2Resize).height(h2);
            }
        }
