        if (isResize) isResize = false;
        $("body").removeClass("noselect");
        $(document).unbind("mousemove", _funMoveResize);
        $(document).unbind("mouseup", _funUpResize);
    };

    $(".g_resize_height").mousedown(function (e) {
        var gridDir = $(this).closest("#content").find(".dir");
        oG1Resize = $(gridDir.get(0));
        oG2Resize = $(gridDir.get(1));
console.log(oG1Resize)
console.log(oG2Resize)
        isResize = true;
        iStartY = e.pageY;
        iG1Height = oG1Resize.height();
        iG2Height = oG2Resize.height();
        $("body").addClass("noselect");

        $(document).bind("mousemove", _funMoveResize);
        $(document).bind("mouseup", _funUpResize);
    });

    */

    var gridDir = $("#content").find(".dir");
    var oG1Resize = $(gridDir.get(0));
    var oG2Resize = $(gridDir.get(1));
    $("#bar_resize_grid").boxresize({ divBox1: oG1Resize, divBox2: oG2Resize, resizeWidth: false});

    //end

    var s = '<button class="btn-action btn-action-v1" id="btnTreeAction"><div class="icon-btn-bottom ic-hide-tree" id="ic_btn_action_tree"></div></button>'
    $("#content").append(s);

    $("#btnTreeAction").click(function () {
        var icBtn = $("#ic_btn_action_tree");
        if (!p.options._isShow){
          p.options._isShow = true;

          var curLeft = $("#content").css("margin-left");

          moveLeft("tree_left", "-=" + curLeft);
          moveLeft("content", "-=" + curLeft);

          setTimeout(function(){
            icBtn.removeClass("ic-hide-tree");
            icBtn.addClass("ic-show-tree");
          }, 300);
        }else{
          p.options._isShow = false;

          var curLeft = $("#tree_left").css("width");
          moveLeft("tree_left", "+=" + curLeft);
          moveLeft("content", "+=" + curLeft);

          setTimeout(function(){
            icBtn.removeClass("ic-show-tree");
            icBtn.addClass("ic-hide-tree");
          }, 300);
        }
    });
  }
}

function refreshSizeGridDir(){
  var wHeight = $(window).height(), hBar = 70;
  if($(window).width() < 767)
    hBar = 60;
  $("#content").css("height", (wHeight - hBar) + "px");
}

function moveLeft(id, action){
  $("#" + id).animate({
      marginLeft: action
  }, 500);
}

function loadTreeDept(p, d){
  var d = new DataTable(d);
  debugger;
  var leftPanel = $("#tree_left");
  var treeBottom = $("#tree_info");
  var dContent = $("#content");
  var fTree = $("#tree_dept").treeview({ tblData: d, expandAll: true, showCheck: true, minWidth: 95, inRight: false
      , onSelectedItem: function(tr, v, v2){
        var m = p.options.memvars, vtext = (v == '')?$.msg.get('AllLabel'):v;
        m.val('ma_bp', 'C', v2, 'FIND')
        p._setOptions({memvars:m, subtitle: ['{rg_code}', vtext, '%s2', '']});
      }, onCheckedItem: function(tr, v, flag){
        var m = p.options.memvars, v2 = tr.getCheckedItem(), vtext = (v2 == '') ? $.msg.get('AllLabel') : v2;
        m.val('ma_bp', 'C', v2, 'FIND')
        p._setOptions({memvars:m, subtitle: ['{rg_code}', vtext, '%s2', '']});
      }, onResizeTree: function(tr, w){
        leftPanel.width(w);
        treeBottom.width(w);

        dContent.css("margin-left", (w+1) + "px");
      }
    });
}
function loadTreeInfo(p, d){
  var d = new DataTable(d);
  var dContent = $("#content");

  var fTree = $("#tree_info").treeview({ tblData: d, expandAll: true, showCheck: false, minWidth: 95
      , onSelectedItem: function(tr, v, v2){
        var m = p.options.memvars, vtext = (v == '')?$.msg.get('AllLabel'):v;
        m.val('ma_bp', 'C', v2, 'FIND')
        p._setOptions({memvars:m, subtitle: ['{rg_code}', vtext, '%s2', '']});
      }, onCheckedItem: function(tr, v, flag){
        var m = p.options.memvars, v2 = tr.getCheckedItem(), vtext = (v2 == '') ? $.msg.get('AllLabel') : v2;
        m.val('ma_bp', 'C', v2, 'FIND')
        p._setOptions({memvars:m, subtitle: ['{rg_code}', vtext, '%s2', '']});
      }
    });
}

css.text:

.bottom-resize {
    display: block;
    width: 100%;
    height: 5px;
    margin-top: -4px;
    position: absolute;
    cursor: n-resize;
}

#content{
  margin-left: 300px;
}
.tree-form{
    width: 300px;
}
.table-bottom{
  height: calc(100% - 77px);
  top: 0px;
  position: relative;
  margin-top: 27px;
  clear: both;
  border-bottom: 1px solid #ddd;
}
.left-panel-tree{
  width: 300px;
  height: 100%;
  position: absolute;
  margin-left: 1px;
}
.dir{
  position: relative !important;
  height: 50%;
}

.ic-hide-tree{
  background-position: -108px 0px;
}
.ic-show-tree{
  background-position: 0px 0px;
}

.tree-top{
  height: calc(50% - 33px);
  border-bottom: 1px solid #ddd;
  border-right: 1px solid #ddd;
}
.tree-bottom{
  height: calc(50% - 38px);
  border-right: 1px solid #ddd;
}
.tree-bottom .right-resize{
  display: none;
}

@media only screen and (max-width: 767px) {
  .table-bottom{
    margin-top: 42px;
    height: calc(100% - 92px);
  }
  .left-panel-tree{
    margin-top: -5px;
  }
}
